import pluggy

# The "Product/UX" deliverable: Formal contracts for our ecosystem.
# These are the service primitives.

hookspec = pluggy.HookspecMarker("agent_kernel")

class AgentSpec:
    """Specification for an Agent plugin."""
    @hookspec
    def execute_task(self, task: str) -> str:
        """
        Accepts a task string, returns a string artifact (e.g., code, data).
        This is the core work function of an agent.
        """

class EvaluatorSpec:
    """Specification for an Evaluator plugin."""
    @hookspec
    def evaluate_artifact(self, artifact: dict) -> dict:
        """
        Accepts a dictionary artifact (structured execution results), returns a dictionary with score and details.
        The dictionary must contain a 'score' (float, 0.0-1.0) and can contain other metadata.
        """
